with inserted as (
  insert into public.surveys (slug, name, status, config, published_version)
  values ('prompt-gp', 'Diagnóstico PromptGP: prompts para Gestão de Projetos', 'published', '{"product":"prompt-gp","type":"maturity-diagnostic","checkout_url":"https://chk.eduzz.com/iglxf4to","steps":[{"id":"intro","kind":"intro","title":"Pare de improvisar perguntas para a IA.","body":"Você já usa IA para resolver desafios de gestão de projetos?\n[[QF_INTRO_IMAGE:https://forms.trentim.com/books/promptgp-offer.webp]]","cta":"Começar diagnóstico","art":"hero"},{"id":"prompt-start-response","kind":"branch","variants":{"sim":{"title":"Usar IA é o começo. Saber pedir muda o resultado.","body":"Vamos descobrir se seus prompts oferecem contexto, objetivo, formato e critérios suficientes para apoiar decisões reais de projeto."},"nao":{"title":"Você pode começar com uma estrutura simples.","body":"Não precisa dominar IA para fazer este diagnóstico. Responda como abordaria as situações; ao final, você verá por onde começar."}}},{"id":"prompt-q1","kind":"question","title":"Consigo explicar à IA o contexto do projeto antes de pedir uma resposta.","input":"scale","dimension":"estrutura_prompt","options":[{"label":"Discordo totalmente","value":"1","score":0},{"label":"Discordo","value":"2","score":1},{"label":"Nem concordo nem discordo","value":"3","score":2},{"label":"Concordo","value":"4","score":3},{"label":"Concordo totalmente","value":"5","score":4}]},{"id":"prompt-q2","kind":"question","title":"Sei definir o objetivo e o papel que a IA deve assumir em um prompt.","input":"scale","dimension":"estrutura_prompt","options":[{"label":"Discordo totalmente","value":"1","score":0},{"label":"Discordo","value":"2","score":1},{"label":"Nem concordo nem discordo","value":"3","score":2},{"label":"Concordo","value":"4","score":3},{"label":"Concordo totalmente","value":"5","score":4}]},{"id":"prompt-q3","kind":"question","title":"Especifico o formato da resposta e os critérios para avaliar sua utilidade.","input":"scale","dimension":"estrutura_prompt","options":[{"label":"Discordo totalmente","value":"1","score":0},{"label":"Discordo","value":"2","score":1},{"label":"Nem concordo nem discordo","value":"3","score":2},{"label":"Concordo","value":"4","score":3},{"label":"Concordo totalmente","value":"5","score":4}]},{"id":"prompt-q4","kind":"question","title":"Consigo usar IA para decompor objetivos em escopo e entregáveis verificáveis.","input":"scale","dimension":"planejamento_escopo","options":[{"label":"Discordo totalmente","value":"1","score":0},{"label":"Discordo","value":"2","score":1},{"label":"Nem concordo nem discordo","value":"3","score":2},{"label":"Concordo","value":"4","score":3},{"label":"Concordo totalmente","value":"5","score":4}]},{"id":"prompt-q5","kind":"question","title":"Consigo pedir à IA alternativas de cronograma considerando premissas e dependências.","input":"scale","dimension":"planejamento_escopo","options":[{"label":"Discordo totalmente","value":"1","score":0},{"label":"Discordo","value":"2","score":1},{"label":"Nem concordo nem discordo","value":"3","score":2},{"label":"Concordo","value":"4","score":3},{"label":"Concordo totalmente","value":"5","score":4}]},{"id":"prompt-q6","kind":"question","title":"Reviso as respostas da IA com dados do projeto antes de utilizá-las.","input":"scale","dimension":"analise_decisao","options":[{"label":"Discordo totalmente","value":"1","score":0},{"label":"Discordo","value":"2","score":1},{"label":"Nem concordo nem discordo","value":"3","score":2},{"label":"Concordo","value":"4","score":3},{"label":"Concordo totalmente","value":"5","score":4}]},{"id":"prompt-context-1","kind":"insight","eyebrow":"PromptGP | estrutura do pedido","title":"A qualidade da resposta começa na qualidade do contexto.","body":"O PromptGP apresenta uma estrutura de cinco partes para orientar o pedido: persona, contexto, objetivo, formato de saída e critérios. Ela ajuda a transformar uma pergunta vaga em uma tarefa verificável.","icons":[{"emoji":"1","text":"Persona: quem a IA deve representar"},{"emoji":"2","text":"Contexto e objetivo: situação e tarefa"},{"emoji":"3","text":"Formato e critérios: como entregar e avaliar"}],"source":"Mario Trentim, PromptGP, cap. 2","visual":"chart"},{"id":"prompt-q7","kind":"question","title":"Você precisa elaborar um termo de abertura com IA. Qual pedido faria?","input":"single","dimension":"planejamento_escopo","options":[{"label":"Escreva um termo de abertura para um projeto.","value":"0","score":0},{"label":"Escreva um termo de abertura para a implantação de um sistema.","value":"1","score":1},{"label":"Com base no objetivo e nas partes interessadas, sugira seções para um termo de abertura.","value":"2","score":2},{"label":"Atue como GP; use objetivo, benefícios, restrições e partes interessadas informados; proponha um termo de abertura com premissas e dúvidas a validar.","value":"3","score":3}]},{"id":"prompt-q8","kind":"question","title":"O escopo está confuso e há solicitações contraditórias. Como pediria apoio à IA?","input":"single","dimension":"planejamento_escopo","options":[{"label":"Peça que a IA escreva o escopo completo sozinha.","value":"0","score":0},{"label":"Envie uma lista de tarefas e peça um resumo.","value":"1","score":1},{"label":"Forneça objetivos e pedidos para separar entregáveis e dúvidas.","value":"2","score":2},{"label":"Forneça objetivos, limites e solicitações; peça entregáveis, exclusões, critérios de aceite e perguntas para resolver conflitos.","value":"3","score":3}]},{"id":"prompt-q9","kind":"question","title":"O cronograma parece inviável. Qual prompt produziria uma análise útil?","input":"single","dimension":"planejamento_escopo","options":[{"label":"Pergunte se o cronograma está certo.","value":"0","score":0},{"label":"Peça um novo cronograma mais curto.","value":"1","score":1},{"label":"Informe atividades e datas para identificar atrasos potenciais.","value":"2","score":2},{"label":"Informe dependências, capacidade, marcos e restrições; peça cenários, premissas, riscos e trade-offs para decisão humana.","value":"3","score":3}]},{"id":"prompt-context-2","kind":"insight","eyebrow":"PromptGP | planejamento","title":"Um prompt útil acompanha o ciclo do projeto.","body":"O livro reúne aplicações para iniciação, escopo, cronograma e custos. Em cada caso, a IA trabalha melhor quando recebe premissas e restrições reais e quando as saídas são revisadas pelo gerente.","stat":"O comando deve ajudar a pensar e decidir, não substituir a validação do projeto.","source":"Mario Trentim, PromptGP, caps. 3–6","visual":"sparkle"},{"id":"prompt-q10","kind":"question","title":"Um fornecedor oferece uma proposta barata, mas incompleta. Como usaria IA?","input":"single","dimension":"analise_decisao","options":[{"label":"Peça à IA que escolha o fornecedor.","value":"0","score":0},{"label":"Compare apenas os preços das propostas.","value":"1","score":1},{"label":"Peça uma lista de diferenças entre as propostas.","value":"2","score":2},{"label":"Forneça requisitos e critérios ponderados; peça lacunas, riscos contratuais, perguntas ao fornecedor e comparação explicável.","value":"3","score":3}]},{"id":"prompt-q11","kind":"question","title":"Um risco de atraso foi identificado. Qual seria o melhor uso do prompt?","input":"single","dimension":"analise_decisao","options":[{"label":"Peça que a IA elimine o risco.","value":"0","score":0},{"label":"Peça uma lista genérica de riscos.","value":"1","score":1},{"label":"Descreva o risco e peça ações possíveis.","value":"2","score":2},{"label":"Informe causa, probabilidade, impacto e gatilhos; peça respostas, responsáveis, contingências e sinais de acompanhamento.","value":"3","score":3}]},{"id":"prompt-q12","kind":"question","title":"Os custos do projeto subiram. Como prepararia uma decisão com IA?","input":"single","dimension":"analise_decisao","options":[{"label":"Peça para reduzir o orçamento em 20%.","value":"0","score":0},{"label":"Solicite um resumo do orçamento.","value":"1","score":1},{"label":"Informe valores planejados e reais e peça causas prováveis.","value":"2","score":2},{"label":"Forneça linha de base, custos reais e mudanças; peça causas, projeções, cenários e impactos para validação com finanças.","value":"3","score":3}]},{"id":"prompt-context-3","kind":"insight","eyebrow":"PromptGP | análise","title":"Riscos e escolhas exigem critérios explícitos.","body":"Ao analisar custos, riscos, qualidade ou fornecedores, peça alternativas, efeitos e pontos de incerteza. A decisão depende de dados confiáveis, julgamento profissional e contexto organizacional.","stat":"Um bom prompt explicita o que comparar e o que ainda precisa ser confirmado.","source":"Mario Trentim, PromptGP, caps. 6, 8, 9 e 11","visual":"chart"},{"id":"prompt-q13","kind":"question","title":"Você precisa comunicar um atraso a públicos diferentes. O que pediria?","input":"single","dimension":"comunicacao_monitoramento","options":[{"label":"Peça um comunicado único para todos.","value":"0","score":0},{"label":"Peça um texto positivo que esconda o atraso.","value":"1","score":1},{"label":"Peça versões de mensagem para equipe e patrocinador.","value":"2","score":2},{"label":"Informe fatos, impacto e plano de ação; peça versões para cada público com decisões, responsáveis e tom adequado, sem omitir riscos.","value":"3","score":3}]},{"id":"prompt-q14","kind":"question","title":"Após uma reunião, como transformaria anotações em acompanhamento?","input":"single","dimension":"comunicacao_monitoramento","options":[{"label":"Peça um resumo livre da reunião.","value":"0","score":0},{"label":"Peça uma ata e envie sem revisão.","value":"1","score":1},{"label":"Peça decisões e tarefas a partir das notas.","value":"2","score":2},{"label":"Forneça notas sem dados sensíveis; peça decisões, ações, responsáveis, prazos, pendências e itens incertos para revisão.","value":"3","score":3}]},{"id":"prompt-q15","kind":"question","title":"O patrocinador pede um status executivo. Qual prompt seria mais eficaz?","input":"single","dimension":"comunicacao_monitoramento","options":[{"label":"Peça um relatório que diga que está tudo bem.","value":"0","score":0},{"label":"Peça um resumo longo de todas as tarefas.","value":"1","score":1},{"label":"Forneça dados de progresso e peça um status curto.","value":"2","score":2},{"label":"Forneça linha de base, progresso, riscos e decisões; peça síntese executiva com desvios, consequências, próximos passos e dúvidas.","value":"3","score":3}]},{"id":"prompt-context-4","kind":"insight","eyebrow":"PromptGP | comunicação e monitoramento","title":"A IA ajuda a transformar informação em ação acompanhável.","body":"Com contexto e formato definidos, prompts podem apoiar comunicação com partes interessadas, gestão de equipes, reuniões e relatórios de acompanhamento. Revise fatos, destinatários e próximos passos antes de compartilhar.","stat":"Clareza no pedido. Critério na revisão. Mais utilidade na entrega.","source":"Mario Trentim, PromptGP, caps. 7, 10 e 12","visual":"people"},{"id":"prompt-pattern","kind":"insight","eyebrow":"Quase lá","title":"Seu padrão de uso já está aparecendo.","body":"Cruzamos suas respostas sobre estrutura de prompt, planejamento, análise e comunicação para identificar os pontos em que um método pode ajudá-lo mais.","stat":"O resultado reflete suas escolhas em situações concretas.","visual":"sparkle"},{"id":"salary-range","kind":"question","title":"Qual é sua faixa salarial atual?","subtitle":"Essa informação ajuda a contextualizar seu momento profissional.","input":"single","options":[{"label":"Até R$ 5.000","value":"faixa1"},{"label":"R$ 5.001 a R$ 10.000","value":"faixa2"},{"label":"R$ 10.001 a R$ 15.000","value":"faixa3"},{"label":"R$ 15.001 a R$ 25.000","value":"faixa4"},{"label":"Acima de R$ 25.000","value":"faixa5"}]},{"id":"email","kind":"email","title":"Seu diagnóstico está quase pronto. Qual e-mail devemos usar para liberar o resultado?"},{"id":"name","kind":"name","title":"E como podemos chamar você?"},{"id":"processing","kind":"processing","title":"Gerando seu diagnóstico PromptGP..."},{"id":"insight-pre-result-guide","kind":"insight","eyebrow":"Seu mapa de prompts está pronto","title":"Agora vamos ao seu resultado, {{nome}}!","body":"Você verá seu nível atual e as situações em que um prompt mais claro pode melhorar seu trabalho em projetos.","stat":"Pare de improvisar perguntas para a IA. Tenha o prompt certo para cada desafio da gestão de projetos.","source":"Mario Trentim, PromptGP, 2026","visual":"sparkle"},{"id":"result","kind":"result"}],"draft_steps":[{"id":"intro","kind":"intro","title":"Pare de improvisar perguntas para a IA.","body":"Você já usa IA para resolver desafios de gestão de projetos?\n[[QF_INTRO_IMAGE:https://forms.trentim.com/books/promptgp-offer.webp]]","cta":"Começar diagnóstico","art":"hero"},{"id":"prompt-start-response","kind":"branch","variants":{"sim":{"title":"Usar IA é o começo. Saber pedir muda o resultado.","body":"Vamos descobrir se seus prompts oferecem contexto, objetivo, formato e critérios suficientes para apoiar decisões reais de projeto."},"nao":{"title":"Você pode começar com uma estrutura simples.","body":"Não precisa dominar IA para fazer este diagnóstico. Responda como abordaria as situações; ao final, você verá por onde começar."}}},{"id":"prompt-q1","kind":"question","title":"Consigo explicar à IA o contexto do projeto antes de pedir uma resposta.","input":"scale","dimension":"estrutura_prompt","options":[{"label":"Discordo totalmente","value":"1","score":0},{"label":"Discordo","value":"2","score":1},{"label":"Nem concordo nem discordo","value":"3","score":2},{"label":"Concordo","value":"4","score":3},{"label":"Concordo totalmente","value":"5","score":4}]},{"id":"prompt-q2","kind":"question","title":"Sei definir o objetivo e o papel que a IA deve assumir em um prompt.","input":"scale","dimension":"estrutura_prompt","options":[{"label":"Discordo totalmente","value":"1","score":0},{"label":"Discordo","value":"2","score":1},{"label":"Nem concordo nem discordo","value":"3","sc